    "CREATED_AT" TIMESTAMP WITH TIME ZONE COMMENT 'Timestamp when the config was inserted' NOT NULL,
    "UPDATED_AT" TIMESTAMP WITH TIME ZONE COMMENT 'Timestamp when the config was updated' NOT NULL
);
