CREATE TABLE "PUBLIC"."SOURCE_REPLACEMENT_RUN" COMMENT 'Table to track source replacement executions and their status'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Unique ID' NOT NULL,
    "SOURCE_ENTITY_TYPE" CHARACTER VARYING(50) COMMENT 'Type of the source entity (card or table)' NOT NULL,
    "SOURCE_ENTITY_ID" INTEGER COMMENT 'ID of the source entity' NOT NULL,
    "TARGET_ENTITY_TYPE" CHARACTER VARYING(50) COMMENT 'Type of the target entity (card or table)' NOT NULL,
    "TARGET_ENTITY_ID" INTEGER COMMENT 'ID of the target entity' NOT NULL,
    "STATUS" CHARACTER VARYING(50) COMMENT 'Current status (started, succeeded, failed, canceled, timeout)' NOT NULL,
    "IS_ACTIVE" BOOLEAN COMMENT 'True only for currently running replacements, null for completed',
    "PROGRESS" FLOAT COMMENT 'Progress from 0.0 to 1.0',
    "MESSAGE" CHARACTER LARGE OBJECT COMMENT 'Human-readable message; may contain error info',
    "USER_ID" INTEGER COMMENT 'User who initiated the replacement',
    "START_TIME" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'When the replacement started' NOT NULL,
    "END_TIME" TIMESTAMP WITH TIME ZONE COMMENT 'When the replacement completed (null if still running)'
);
--;;
