CREATE TABLE "PUBLIC"."METABASE_TABLE_IMPORT" COMMENT 'Staging table for the metadata file importer''s tables phase. Drained outside the merge txn, merged into metabase_table inside it.'(
    "SOURCE_ID" INTEGER COMMENT U&'Wire :id \2014 source appdb''s metabase_table.id. Unique within one file.' NOT NULL,
    "SOURCE_DB_ID" INTEGER COMMENT U&'Wire :db_id \2014 references the source-side database row in :databases[].' NOT NULL,
    "DB_NAME" CHARACTER VARYING(254) COMMENT 'Denormalized from :databases[] at drain time, used for natural-key match against target.' NOT NULL,
    "SCHEMA" CHARACTER VARYING(254) COMMENT 'Mirrors metabase_table.schema nullability.',
    "NAME" CHARACTER VARYING(254) COMMENT U&'Wire :name \2014 table''s natural-key name component.' NOT NULL,
    "DESCRIPTION" CHARACTER LARGE OBJECT COMMENT U&'Wire :description \2014 clobbered onto metabase_table.description on merge.',
    "DISPLAY_NAME" CHARACTER VARYING(254) COMMENT 'Pre-humanized at drain time so the merge SQL doesn''t replicate the algorithm in three dialects.',
    "TARGET_ID" INTEGER COMMENT U&'Resolved by table-resolve step; \2192 metabase_table.id. NULL means no live row matches; row is an insert candidate.'
);
--;;
ALTER TABLE "PUBLIC"."METABASE_TABLE_IMPORT" ADD CONSTRAINT "PUBLIC"."PK_METABASE_TABLE_IMPORT" PRIMARY KEY("SOURCE_ID");
--;;
CREATE INDEX "PUBLIC"."IDX_MTI_TARGET_ID" ON "PUBLIC"."METABASE_TABLE_IMPORT"("TARGET_ID" NULLS FIRST);
--;;
