CREATE TABLE "PUBLIC"."METABASE_TABLE"(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "CREATED_AT" TIMESTAMP WITH TIME ZONE NOT NULL,
    "UPDATED_AT" TIMESTAMP WITH TIME ZONE NOT NULL,
    "NAME" CHARACTER VARYING(256) NOT NULL,
    "DESCRIPTION" CHARACTER LARGE OBJECT,
    "ENTITY_TYPE" CHARACTER VARYING(254),
    "ACTIVE" BOOLEAN NOT NULL,
    "DB_ID" INTEGER NOT NULL,
    "DISPLAY_NAME" CHARACTER VARYING(256),
    "VISIBILITY_TYPE" CHARACTER VARYING(254),
    "SCHEMA" CHARACTER VARYING(254),
    "POINTS_OF_INTEREST" CHARACTER LARGE OBJECT,
    "CAVEATS" CHARACTER LARGE OBJECT,
    "SHOW_IN_GETTING_STARTED" BOOLEAN DEFAULT FALSE NOT NULL,
    "FIELD_ORDER" CHARACTER VARYING(254) DEFAULT 'database' NOT NULL,
    "INITIAL_SYNC_STATUS" CHARACTER VARYING(32) DEFAULT 'complete' COMMENT 'String indicating whether a table has completed its initial sync and is ready to use' NOT NULL,
    "IS_UPLOAD" BOOLEAN DEFAULT FALSE COMMENT 'Was the table created from user-uploaded (i.e., from a CSV) data?' NOT NULL,
    "DATABASE_REQUIRE_FILTER" BOOLEAN COMMENT 'If true, the table requires a filter to be able to query it',
    "ESTIMATED_ROW_COUNT" BIGINT COMMENT 'The estimated row count',
    "VIEW_COUNT" INTEGER DEFAULT 0 COMMENT 'Keeps a running count of card views' NOT NULL,
    "IS_DEFECTIVE_DUPLICATE" BOOLEAN DEFAULT 'false' COMMENT 'Indicates whether the table is a defective duplicate that should never have been created.' NOT NULL,
    "UNIQUE_TABLE_HELPER" CHARACTER VARYING(254) GENERATED ALWAYS AS (CASE WHEN "IS_DEFECTIVE_DUPLICATE" = TRUE THEN NULL ELSE COALESCE("SCHEMA", '') END),
    "DEACTIVATED_AT" TIMESTAMP WITH TIME ZONE COMMENT 'The timestamp when the table was deactivated (active changed from true to false)',
    "ARCHIVED_AT" TIMESTAMP WITH TIME ZONE COMMENT 'The timestamp when the table was marked for archiving',
    "IS_WRITABLE" BOOLEAN COMMENT 'true if current connection can insert, update and delete rows from this table',
    "DATA_AUTHORITY" CHARACTER VARYING(20) DEFAULT 'unconfigured' COMMENT 'Indicates the data authority status - unconfigured, authoritative, computed, or ingested' NOT NULL,
    "DATA_SOURCE" CHARACTER VARYING(254) COMMENT 'The origin type of the data (e.g. metabase-transform)',
    "DATA_LAYER" CHARACTER VARYING(254) DEFAULT 'internal' COMMENT 'The (new) enum for visibility class',
    "OWNER_EMAIL" CHARACTER LARGE OBJECT COMMENT 'An optional email address of the ''owner'' of this table, exclusive with owner_user_id.',
    "OWNER_USER_ID" INTEGER COMMENT 'An (metabase) user id of the ''owner'' of this table, exclusive with owner_email.',
    "COLLECTION_ID" INTEGER COMMENT 'The collection this table is published to (null if not published or published to root)',
    "IS_PUBLISHED" BOOLEAN DEFAULT FALSE COMMENT 'Whether this table is published' NOT NULL,
    "TRANSFORM_ID" INTEGER COMMENT 'Foreign key to the transform that created this table',
    "TRANSFORM_TARGET" BOOLEAN DEFAULT FALSE COMMENT 'Whether any transform is configured to target this table. Conservative: eagerly set to true when a transform targets this table (never stale in this direction), cleared asynchronously when no transforms reference it anymore (may have false positives, never false negatives).' NOT NULL
);
--;;
