CREATE TABLE "PUBLIC"."DEPENDENCY_STATUS" COMMENT 'Tracks dependency calculation status for entities, analogous to analysis_finding'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "ENTITY_TYPE" CHARACTER VARYING(254) COMMENT 'The type of the entity (card, transform, snippet, etc.)' NOT NULL,
    "ENTITY_ID" INTEGER COMMENT 'The ID of the entity' NOT NULL,
    "DEPENDENCY_ANALYSIS_VERSION" SMALLINT DEFAULT 0 COMMENT 'Version of the dependency analysis that was performed' NOT NULL,
    "STALE" BOOLEAN DEFAULT FALSE COMMENT 'True when the entity needs dependency recalculation' NOT NULL,
    "FAIL_COUNT" INTEGER DEFAULT 0 COMMENT 'Number of consecutive failed dependency calculation attempts' NOT NULL,
    "NEXT_RETRY_AT" TIMESTAMP WITH TIME ZONE COMMENT 'Earliest time at which a failed entity can be retried (null means immediately processable)',
    "TERMINAL" BOOLEAN DEFAULT FALSE COMMENT 'True when the entity has exceeded max retries and should not be retried until modified' NOT NULL
