CREATE TABLE "PUBLIC"."DATA_COMPLEXITY_SCORE" COMMENT 'Append-only snapshots of the computed Data Complexity Score shown in the Metabot overview UI'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "FINGERPRINT" CHARACTER VARYING(512) COMMENT 'Fingerprint of the scoring inputs (formula version, synonym threshold, embedding model)' NOT NULL,
    "SCORE_DATA" CHARACTER LARGE OBJECT COMMENT 'JSON-serialized complexity score response returned by the data-complexity-score endpoint' NOT NULL,
    "CREATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'When this score snapshot was computed and stored' NOT NULL,
    "SOURCE" CHARACTER VARYING(255) DEFAULT 'appdb' COMMENT U&'Provenance \2014 "appdb" for cron/API/CLI-from-appdb, or "representation:<digest>" for CLI runs that scored a representation directory.' NOT NULL
