CREATE TABLE "PUBLIC"."METABASE_FIELD_IMPORT" COMMENT 'Staging table for the metadata file importer''s fields phase. Drained outside the merge txn, depth-tagged, then merged into metabase_field level by level inside the txn.'(
    "SOURCE_ID" INTEGER COMMENT U&'Wire :id \2014 source appdb''s metabase_field.id. Unique within one file.' NOT NULL,
    "SOURCE_TABLE_ID" INTEGER COMMENT U&'Wire :table_id \2014 references metabase_table_import.source_id within the same file.' NOT NULL,
    "SOURCE_PARENT_ID" INTEGER COMMENT U&'Wire :parent_id \2014 references another metabase_field_import.source_id within the same file. NULL for top-level fields.',
    "SOURCE_FK_TARGET_ID" INTEGER COMMENT U&'Wire :fk_target_field_id \2014 references another metabase_field_import.source_id. NULL for non-FK fields.',
    "NAME" CHARACTER VARYING(254) COMMENT U&'Wire :name \2014 field''s natural-key name component (within its parent + table).' NOT NULL,
    "BASE_TYPE" CHARACTER VARYING(254) COMMENT U&'Wire :base_type \2014 clobbered onto metabase_field.base_type on merge.' NOT NULL,
    "DATABASE_TYPE" CHARACTER VARYING(254) COMMENT U&'Wire :database_type \2014 clobbered onto metabase_field.database_type on merge.' NOT NULL,
    "EFFECTIVE_TYPE" CHARACTER VARYING(254) COMMENT U&'NULL when wire row omitted it (\2261 base_type). Importer treats NULL as base_type on INSERT; leaves target alone on UPDATE.',
    "SEMANTIC_TYPE" CHARACTER VARYING(254) COMMENT U&'Wire :semantic_type \2014 clobbered onto metabase_field.semantic_type on merge.',
    "COERCION_STRATEGY" CHARACTER VARYING(254) COMMENT U&'Wire :coercion_strategy \2014 clobbered onto metabase_field.coercion_strategy on merge.',
    "DESCRIPTION" CHARACTER LARGE OBJECT COMMENT U&'Wire :description \2014 clobbered onto metabase_field.description on merge.',
    "NFC_PATH" CHARACTER LARGE OBJECT COMMENT U&'NULL for empty/absent paths, JSON-encoded array string otherwise \2014 same encoding as metabase_field.nfc_path.',
    "DEPTH" INTEGER COMMENT 'Populated once after drain by the depth-tagging step. 0 = root (no parent, no fk_target). Higher = max(parent depth, fk_target depth) + 1. NULL after depth-tagging means a cycle in the file''s reference graph.',
    "TARGET_ID" INTEGER COMMENT 'Resolved per-depth-level by natural-key match against metabase_field. NULL means no live row matches; row is an insert candidate at this depth.',
    "TARGET_TABLE_ID" INTEGER COMMENT 'Populated from the table-resolve step before the depth walk starts. Joined-through from metabase_table_import.target_id.',
    "TARGET_PARENT_ID" INTEGER COMMENT U&'Populated per-depth-level by self-join on source_parent_id \2192 another row''s target_id.',
    "TARGET_FK_TARGET_ID" INTEGER COMMENT U&'Populated per-depth-level by self-join on source_fk_target_id \2192 another row''s target_id.'
);
--;;
ALTER TABLE "PUBLIC"."METABASE_FIELD_IMPORT" ADD CONSTRAINT "PUBLIC"."PK_METABASE_FIELD_IMPORT" PRIMARY KEY("SOURCE_ID");
--;;
CREATE INDEX "PUBLIC"."IDX_MFI_DEPTH" ON "PUBLIC"."METABASE_FIELD_IMPORT"("DEPTH" NULLS FIRST);
--;;
CREATE INDEX "PUBLIC"."IDX_MFI_TARGET_ID" ON "PUBLIC"."METABASE_FIELD_IMPORT"("TARGET_ID" NULLS FIRST);
--;;
