    "EMBEDDING_ROUTE" CHARACTER VARYING(64) COMMENT 'API route surface (e.g. public, guest-embed, metabot, agent-api)',
    "METABASE_VERSION" CHARACTER VARYING(32) COMMENT 'Metabase server version tag at time of insert'
);
