    "PROMPT_TOKENS" INTEGER COMMENT 'Number of input/prompt tokens' NOT NULL,
    "COMPLETION_TOKENS" INTEGER COMMENT 'Number of output/completion tokens' NOT NULL,
    "TOTAL_TOKENS" INTEGER COMMENT 'Sum of prompt_tokens + completion_tokens' NOT NULL,
    "USER_ID" INTEGER COMMENT 'Metabase user who triggered the call. NULL for system/background calls.',
    "TENANT_ID" INTEGER COMMENT 'Snapshot of user tenant at request time. NULL for non-tenant users.',
    "CONVERSATION_ID" CHARACTER VARYING(36) COMMENT 'Reference to metabot_conversation. NULL for non-conversational calls.',
    "PROFILE_ID" CHARACTER VARYING(100) COMMENT 'AI profile used, e.g. nlq, sql, slackbot',
    "REQUEST_ID" CHARACTER VARYING(36) COMMENT 'UUID for correlating with Snowplow events',
    "AI_PROXIED" BOOLEAN COMMENT 'Whether this call was routed through the Metabase Cloud AI proxy (true) or directly via BYOK keys (false). Null for rows created before this migration.',
    "CACHE_CREATION_TOKENS" INTEGER COMMENT 'Number of input tokens written to the provider prompt cache (Anthropic cache_creation_input_tokens).',
    "CACHE_READ_TOKENS" INTEGER COMMENT 'Number of input tokens served from the provider prompt cache (Anthropic cache_read_input_tokens).'
);
