    "METADATA_SYNC_SCHEDULE" CHARACTER VARYING(254) DEFAULT '0 50 * * * ? *' COMMENT 'The cron schedule string for when this database should undergo the metadata sync process (and analysis for new fields).' NOT NULL,
    "CACHE_FIELD_VALUES_SCHEDULE" CHARACTER VARYING(254) DEFAULT NULL COMMENT 'The cron schedule string for when FieldValues for eligible Fields should be updated.',
    "TIMEZONE" CHARACTER VARYING(254) COMMENT 'Timezone identifier for the database, set by the sync process',
    "IS_ON_DEMAND" BOOLEAN DEFAULT 'false' COMMENT 'Whether we should do On-Demand caching of FieldValues for this DB. This means FieldValues are updated when their Field is used in a Dashboard or Card param.' NOT NULL,
    "AUTO_RUN_QUERIES" BOOLEAN DEFAULT TRUE COMMENT 'Whether to automatically run queries when doing simple filtering and summarizing in the Query Builder.' NOT NULL,
    "REFINGERPRINT" BOOLEAN COMMENT 'Whether or not to enable periodic refingerprinting for this Database.',
    "CACHE_TTL" INTEGER COMMENT 'Granular cache TTL for specific database.',
    "INITIAL_SYNC_STATUS" CHARACTER VARYING(32) DEFAULT 'complete' COMMENT 'String indicating whether a database has completed its initial sync and is ready to use' NOT NULL,
    "CREATOR_ID" INTEGER COMMENT 'ID of the admin who added the database',
    "SETTINGS" CHARACTER LARGE OBJECT COMMENT 'Serialized JSON containing Database-local Settings for this Database',
    "DBMS_VERSION" CHARACTER LARGE OBJECT COMMENT 'A JSON object describing the flavor and version of the DBMS.',
    "IS_AUDIT" BOOLEAN DEFAULT FALSE COMMENT 'Only the app db, visible to admins via auditing should have this set true.' NOT NULL,
    "UPLOADS_ENABLED" BOOLEAN DEFAULT FALSE COMMENT 'Whether uploads are enabled for this database' NOT NULL,
    "UPLOADS_SCHEMA_NAME" CHARACTER LARGE OBJECT COMMENT 'The schema name for uploads',
    "UPLOADS_TABLE_PREFIX" CHARACTER LARGE OBJECT COMMENT 'The prefix for upload table names',
    "IS_ATTACHED_DWH" BOOLEAN DEFAULT FALSE COMMENT 'This is an attached data warehouse, do not serialize it and hide its details from the UI' NOT NULL,
    "ROUTER_DATABASE_ID" INTEGER COMMENT 'The ID of the primary database for this mirror database.',
    "PROVIDER_NAME" CHARACTER VARYING(100) COMMENT 'The name of the hosting provider for the database (e.g., AWS RDS, Azure).',
    "WRITE_DATA_DETAILS" CHARACTER LARGE OBJECT COMMENT 'Encrypted JSON containing connection details for write operations (transforms, etc.)',
    "ADMIN_DETAILS" CHARACTER LARGE OBJECT COMMENT 'Encrypted JSON containing connection details for admin (highest-privilege) operations such as DDL and ownership changes',
    "IS_STUB" BOOLEAN DEFAULT FALSE COMMENT 'Placeholder database created during deserialization; cleared when real details are supplied and the connection test passes' NOT NULL
);
--;;
ALTER TABLE "PUBLIC"."METABASE_DATABASE" ADD CONSTRAINT "PUBLIC"."PK_METABASE_DATABASE" PRIMARY KEY("ID");
--;;
CREATE TABLE "PUBLIC"."METABOT_USED_TABLE" COMMENT 'Record of which database tables Metabot referenced in generated a queries. Source cards, models, and metrics are recursively expanded to their underlying tables before insertion.'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Auto-incrementing primary key' NOT NULL,
    "MESSAGE_ID" INTEGER COMMENT 'FK to the Metabot message whose query referenced this table' NOT NULL,
    "TABLE_ID" INTEGER COMMENT 'FK to the underlying database table the generated query references' NOT NULL,
    "CREATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'When this reference was recorded' NOT NULL
);
--;;
ALTER TABLE "PUBLIC"."METABOT_USED_TABLE" ADD CONSTRAINT "PUBLIC"."PK_METABOT_USED_TABLE" PRIMARY KEY("ID");
--;;
CREATE INDEX "PUBLIC"."IDX_METABOT_USED_TABLE_TABLE_ID" ON "PUBLIC"."METABOT_USED_TABLE"("TABLE_ID" NULLS FIRST);
--;;
CREATE TABLE "PUBLIC"."METABOT_FEEDBACK" COMMENT 'User feedback - positive/negative w/ optional reason + comment'(
    "MESSAGE_ID" INTEGER COMMENT U&'PK + FK to metabot_message.id \2014 enforces 1:1' NOT NULL,
    "POSITIVE" BOOLEAN COMMENT 'true = thumbs up, false = thumbs down' NOT NULL,
    "ISSUE_TYPE" CHARACTER VARYING(64) COMMENT 'Optional structured issue category (e.g. "ui-bug", "not-factual")',
    "FREEFORM_FEEDBACK" CHARACTER LARGE OBJECT COMMENT 'Optional freeform comment',
    "CREATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'When the feedback was submitted' NOT NULL,
    "UPDATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'When the feedback was last updated' NOT NULL,
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Surrogate PK' NOT NULL,
    "USER_ID" INTEGER COMMENT 'The Metabase user who submitted the feedback. Unconstrained int (matches metabot_message.user_id precedent) so audit rows survive user deletion.' NOT NULL
);
--;;
ALTER TABLE "PUBLIC"."METABOT_FEEDBACK" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_FC" PRIMARY KEY("ID");
--;;
CREATE TABLE "PUBLIC"."PULSE"(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "CREATOR_ID" INTEGER NOT NULL,
    "NAME" CHARACTER VARYING(254),
    "CREATED_AT" TIMESTAMP WITH TIME ZONE NOT NULL,
    "UPDATED_AT" TIMESTAMP WITH TIME ZONE NOT NULL,
    "SKIP_IF_EMPTY" BOOLEAN DEFAULT FALSE COMMENT 'Skip a scheduled Pulse if none of its questions have any results' NOT NULL,
    "ALERT_CONDITION" CHARACTER VARYING(254) COMMENT 'Condition (i.e. "rows" or "goal") used as a guard for alerts',
    "ALERT_FIRST_ONLY" BOOLEAN COMMENT 'True if the alert should be disabled after the first notification',
    "ALERT_ABOVE_GOAL" BOOLEAN COMMENT 'For a goal condition, alert when above the goal',
    "COLLECTION_ID" INTEGER COMMENT 'Options ID of Collection this Pulse belongs to.',
    "COLLECTION_POSITION" SMALLINT COMMENT 'Optional pinned position for this item in its Collection. NULL means item is not pinned.',
    "ARCHIVED" BOOLEAN DEFAULT FALSE COMMENT 'Has this pulse been archived?',
    "DASHBOARD_ID" INTEGER COMMENT 'ID of the Dashboard if this Pulse is a Dashboard Subscription.',
    "PARAMETERS" CHARACTER LARGE OBJECT COMMENT 'Let dashboard subscriptions have their own filters' NOT NULL,
    "ENTITY_ID" CHARACTER(21) COMMENT 'Random NanoID tag for unique identity.',
    "DISABLE_LINKS" BOOLEAN DEFAULT FALSE COMMENT 'Whether to disable email subscription links'
);
--;;
ALTER TABLE "PUBLIC"."PULSE" ADD CONSTRAINT "PUBLIC"."PK_PULSE" PRIMARY KEY("ID");
--;;
CREATE INDEX "PUBLIC"."IDX_PULSE_CREATOR_ID" ON "PUBLIC"."PULSE"("CREATOR_ID" NULLS FIRST);
--;;
CREATE INDEX "PUBLIC"."IDX_PULSE_COLLECTION_ID" ON "PUBLIC"."PULSE"("COLLECTION_ID" NULLS FIRST);
--;;
CREATE TABLE "PUBLIC"."METABOT_MESSAGE" COMMENT 'Table to store metabot conversation messages'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Autoincrement PK' NOT NULL,
    "CREATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'created_at' NOT NULL,
    "PROFILE_ID" CHARACTER LARGE OBJECT COMMENT 'ai-service profile used to perform the conversation' NOT NULL,
    "ROLE" CHARACTER VARYING(20) COMMENT 'Role of the sender' NOT NULL,
    "DATA" CHARACTER LARGE OBJECT COMMENT 'Full message content' NOT NULL,
    "USAGE" CHARACTER LARGE OBJECT COMMENT 'Can be null for user messages; {"<model-name>": {"prompt": 1, "completion": 2}}',
    "TOTAL_TOKENS" INTEGER COMMENT 'A sum of all prompt+completion from `usage`' NOT NULL,
    "CONVERSATION_ID" CHARACTER VARYING(36) COMMENT 'Reference to a conversation' NOT NULL,
    "SLACK_MSG_ID" CHARACTER VARYING(255) COMMENT 'Slack message ID (ts) for correlating with Slack thread history',
    "CHANNEL_ID" CHARACTER VARYING(255) COMMENT 'Slack channel ID for correlating Slack responses',
    "DELETED_AT" TIMESTAMP WITH TIME ZONE COMMENT 'Soft delete timestamp for removed Slack metabot responses',
    "DELETED_BY_USER_ID" INTEGER COMMENT 'Metabase user ID who removed the Slack metabot response',
    "USER_ID" INTEGER COMMENT 'Metabase user ID associated with this message',
    "AI_PROXIED" BOOLEAN COMMENT 'Whether this message was routed through the Metabase Cloud AI proxy (true) or directly via BYOK keys (false). Null for messages created before this migration.',
    "EXTERNAL_ID" CHARACTER VARYING(36) COMMENT 'Stable id shared with clients and used to resolve feedback submissions',
    "FINISHED" BOOLEAN DEFAULT TRUE COMMENT 'NULL while in flight, true once completed, false if the client aborted mid-stream.',
    "ERROR" CHARACTER LARGE OBJECT COMMENT 'Error payload from the agent''s error stream part.'
);
--;;
ALTER TABLE "PUBLIC"."METABOT_MESSAGE" ADD CONSTRAINT "PUBLIC"."PK_METABOT_MESSAGE" PRIMARY KEY("ID");
--;;
CREATE INDEX "PUBLIC"."IDX_METABOT_MESSAGE_CONVERSATION_ID" ON "PUBLIC"."METABOT_MESSAGE"("CONVERSATION_ID" NULLS FIRST);
