CREATE TABLE "PUBLIC"."TRANSFORM" COMMENT 'The main table for Transform entities'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Unique ID' NOT NULL,
    "NAME" CHARACTER LARGE OBJECT COMMENT 'Name' NOT NULL,
    "DESCRIPTION" CHARACTER LARGE OBJECT COMMENT 'the description of the transform',
    "SOURCE" CHARACTER LARGE OBJECT COMMENT 'JSON of source' NOT NULL,
    "TARGET" CHARACTER LARGE OBJECT COMMENT 'JSON of target' NOT NULL,
    "ENTITY_ID" CHARACTER(21) COMMENT 'Random NanoID tag for unique identity.',
    "CREATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'The timestamp of when the transform was created' NOT NULL,
    "UPDATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'The timestamp of when the transform was updated' NOT NULL,
    "SOURCE_TYPE" CHARACTER VARYING(32) COMMENT 'The type of transform ("python", "native", or "mbql")' NOT NULL,
    "CREATOR_ID" INTEGER DEFAULT '13371338' COMMENT 'User who created this transform' NOT NULL,
    "SOURCE_DATABASE_ID" INTEGER COMMENT 'The database containing the source data for this transform',
    "COLLECTION_ID" INTEGER COMMENT 'The collection the transform is in',
    "OWNER_USER_ID" INTEGER COMMENT 'The user ID of the owner of this transform (can be different from creator)',
    "OWNER_EMAIL" CHARACTER LARGE OBJECT COMMENT 'An optional email address of the owner of this transform (for external owners), exclusive with owner_user_id',
    "TARGET_DB_ID" INTEGER COMMENT 'Target database ID for the transform output',
    "LAST_CHECKPOINT_VALUE" CHARACTER LARGE OBJECT COMMENT 'Serialized checkpoint watermark value for incremental transforms, temporal as ISO8601',
    "TARGET_TABLE_ID" INTEGER COMMENT 'FK to metabase_table for the transform''s target table',
    "TABLE_DEPENDENCIES" CHARACTER LARGE OBJECT COMMENT 'Precomputed table dependencies (JSON) used for execution ordering and cycle detection. Null means not yet computed.'
);
--;;
