    "NAME" CHARACTER LARGE OBJECT COMMENT 'Document name' NOT NULL,
    "CREATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'The timestamp of when the document was created' NOT NULL,
