    "VIEW_COUNT" INTEGER DEFAULT 0 COMMENT 'Keeps a running count of document views' NOT NULL,
    "COLLECTION_POSITION" INTEGER COMMENT 'Collection position used for pinning documents. Higher numbers = pinned, null = not pinned.',
    "PUBLIC_UUID" CHARACTER(36) COMMENT 'UUID for publicly-accessible version of this document',
