    "UI_DISPLAY_TYPE" CHARACTER VARYING(32) DEFAULT 'cron/raw' COMMENT 'The display type of the schedule, used for the UI only; "cron/raw" or "cron/builder".' NOT NULL,
    "ACTIVE" BOOLEAN DEFAULT TRUE COMMENT 'Whether the job is active. Inactive jobs do not run on schedule.' NOT NULL
);
