    "REDIRECT_URIS" CHARACTER LARGE OBJECT COMMENT 'JSON array of redirect URIs' NOT NULL,
    "GRANT_TYPES" CHARACTER LARGE OBJECT COMMENT 'JSON array of grant types' NOT NULL,
