    "CLIENT_NAME" CHARACTER VARYING(255) COMMENT 'Human-readable client name',
    "CLIENT_URI" CHARACTER LARGE OBJECT COMMENT 'URL of the client home page',
    "LOGO_URI" CHARACTER LARGE OBJECT COMMENT 'URL of the client logo image',
    "CONTACTS" CHARACTER LARGE OBJECT COMMENT 'JSON array of contact strings',
    "REGISTRATION_TYPE" CHARACTER VARYING(50) COMMENT 'static or dynamic' NOT NULL,
    "CLIENT_TYPE" CHARACTER VARYING(50) DEFAULT 'confidential' COMMENT 'confidential or public' NOT NULL,
    "APPLICATION_TYPE" CHARACTER VARYING(50) DEFAULT 'web' COMMENT 'OAuth application type (web or native), defaults to web',
