    "ATOM_FINGERPRINTS" CHARACTER LARGE OBJECT COMMENT 'Sorted JSON array of canonical serialized atom clauses contained in the basket' NOT NULL,
    "ATOM_COUNT" INTEGER COMMENT 'Number of atomic predicates in the basket' NOT NULL,
    "BUCKET_DATE" DATE COMMENT 'UTC day covered by the rollup row' NOT NULL,
    "COUNT" INTEGER COMMENT 'Number of observations for this composite fact on the bucket day' NOT NULL
);
