    "ICON" CHARACTER VARYING(254) COMMENT 'Icon from plugin manifest - asset path resolved to a URL',
    "MANIFEST" CHARACTER LARGE OBJECT COMMENT 'JSON manifest from metabase-plugin.json in the uploaded bundle',
    "METABASE_VERSION" CHARACTER VARYING(254) COMMENT 'Metabase version range requirement from manifest (e.g. ">=1.59 <1.62")',
    "DEV_BUNDLE_URL" CHARACTER VARYING(1024) COMMENT 'Dev server URL for hot-reload development (e.g. http://localhost:5174)'
