CREATE TABLE "PUBLIC"."QUERY_CACHE" COMMENT 'Cached results of queries are stored here when using the DB-based query cache.'(
    "QUERY_HASH" BINARY(32) COMMENT 'The hash of the query dictionary. (This is a 256-bit SHA3 hash of the query dict).' NOT NULL,
    "UPDATED_AT" TIMESTAMP WITH TIME ZONE NOT NULL,
    "RESULTS" BINARY LARGE OBJECT COMMENT 'Cached, compressed results of running the query with the given hash.' NOT NULL,
    "REFRESH_STARTED_AT" TIMESTAMP WITH TIME ZONE COMMENT 'When a process claimed the lease to recompute this expired entry; NULL when no refresh is in progress. Used to elect a single refresher across processes so the others serve stale results.'
);
--;;
ALTER TABLE "PUBLIC"."QUERY_CACHE" ADD CONSTRAINT "PUBLIC"."PK_QUERY_CACHE" PRIMARY KEY("QUERY_HASH");
--;;
CREATE INDEX "PUBLIC"."IDX_QUERY_CACHE_UPDATED_AT" ON "PUBLIC"."QUERY_CACHE"("UPDATED_AT" NULLS FIRST);
--;;
CREATE TABLE "PUBLIC"."OAUTH_ACCESS_TOKEN" COMMENT 'Stores access tokens for the embedded OAuth provider'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Auto-incrementing primary key' NOT NULL,
    "TOKEN" CHARACTER VARYING(255) COMMENT 'The access token string' NOT NULL,
    "USER_ID" INTEGER COMMENT 'FK to core_user.id (null for client_credentials)',
    "CLIENT_ID" CHARACTER VARYING(255) COMMENT 'The OAuth client_id' NOT NULL,
    "SCOPE" CHARACTER LARGE OBJECT COMMENT 'JSON array of scopes' NOT NULL,
    "EXPIRY" BIGINT COMMENT 'Milliseconds since epoch' NOT NULL,
    "RESOURCE" CHARACTER LARGE OBJECT COMMENT 'JSON array of resource URIs',
    "REVOKED_AT" TIMESTAMP WITH TIME ZONE COMMENT 'Null if active',
    "CREATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'Timestamp of token creation' NOT NULL
);
--;;
ALTER TABLE "PUBLIC"."OAUTH_ACCESS_TOKEN" ADD CONSTRAINT "PUBLIC"."PK_OAUTH_ACCESS_TOKEN" PRIMARY KEY("ID");
--;;
CREATE INDEX "PUBLIC"."IDX_OAUTH_ACCESS_TOKEN_EXPIRY" ON "PUBLIC"."OAUTH_ACCESS_TOKEN"("EXPIRY" NULLS FIRST);
--;;
CREATE INDEX "PUBLIC"."IDX_OAUTH_ACCESS_TOKEN_USER_ID" ON "PUBLIC"."OAUTH_ACCESS_TOKEN"("USER_ID" NULLS FIRST);
--;;
CREATE TABLE "PUBLIC"."METABOT_INSTANCE_LIMIT" COMMENT 'Metabot usage limits at the instance or tenant level'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "TENANT_ID" INTEGER COMMENT 'The tenant ID, or null for instance-wide limit',
    "MAX_USAGE" INTEGER COMMENT 'The maximum usage value, interpreted according to the metabot-limit-unit setting. Null is unlimited'
);
--;;
ALTER TABLE "PUBLIC"."METABOT_INSTANCE_LIMIT" ADD CONSTRAINT "PUBLIC"."PK_METABOT_INSTANCE_LIMIT" PRIMARY KEY("ID");
--;;
CREATE TABLE "PUBLIC"."OAUTH_REFRESH_TOKEN" COMMENT 'Stores refresh tokens for the embedded OAuth provider'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Auto-incrementing primary key' NOT NULL,
    "TOKEN" CHARACTER VARYING(255) COMMENT 'The refresh token string' NOT NULL,
    "USER_ID" INTEGER COMMENT 'FK to core_user.id',
    "CLIENT_ID" CHARACTER VARYING(255) COMMENT 'The OAuth client_id' NOT NULL,
    "SCOPE" CHARACTER LARGE OBJECT COMMENT 'JSON array of scopes' NOT NULL,
    "RESOURCE" CHARACTER LARGE OBJECT COMMENT 'JSON array of resource URIs',
    "EXPIRY" BIGINT COMMENT 'Milliseconds since epoch (null means no expiry)',
    "REVOKED_AT" TIMESTAMP WITH TIME ZONE COMMENT 'Null if active',
    "CREATED_AT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'Timestamp of token creation' NOT NULL
);
--;;
ALTER TABLE "PUBLIC"."OAUTH_REFRESH_TOKEN" ADD CONSTRAINT "PUBLIC"."PK_OAUTH_REFRESH_TOKEN" PRIMARY KEY("ID");
