    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "GROUP_ID" INTEGER COMMENT 'The ID of the associated permissions group' NOT NULL,
    "MAX_USAGE" INTEGER COMMENT 'The maximum usage value, interpreted according to the metabot-limit-unit setting' NOT NULL
);
