CREATE TABLE "PUBLIC"."SOURCE_SEGMENT_DAILY" COMMENT 'Daily source-scoped segment usage rollups'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Surrogate primary key' NOT NULL,
    "SOURCE_TYPE" CHARACTER VARYING(254) COMMENT 'Owning source kind for direct or projected facts, or null for canonical mixed facts',
    "SOURCE_ID" INTEGER COMMENT 'Owning table or card ID for direct or projected facts, or null for canonical mixed facts',
    "OWNERSHIP_MODE" CHARACTER VARYING(254) COMMENT 'Ownership attribution mode such as direct, projected, or mixed' NOT NULL,
    "FIELD_ID" INTEGER COMMENT 'Field referenced by the segment fact when applicable',
    "PREDICATE" CHARACTER LARGE OBJECT COMMENT 'Canonical serialized representation of the atomic segment predicate' NOT NULL,
    "BUCKET_DATE" DATE COMMENT 'UTC day covered by the rollup row' NOT NULL,
    "COUNT" INTEGER COMMENT 'Number of observations for this fact on the bucket day' NOT NULL
);
--;;
ALTER TABLE "PUBLIC"."SOURCE_SEGMENT_DAILY" ADD CONSTRAINT "PUBLIC"."PK_SOURCE_SEGMENT_DAILY" PRIMARY KEY("ID");
--;;
CREATE INDEX "PUBLIC"."IDX_SOURCE_SEGMENT_DAILY_BUCKET_SOURCE" ON "PUBLIC"."SOURCE_SEGMENT_DAILY"("BUCKET_DATE" NULLS FIRST, "SOURCE_TYPE" NULLS FIRST, "SOURCE_ID" NULLS FIRST, "OWNERSHIP_MODE" NULLS FIRST);
--;;
CREATE INDEX "PUBLIC"."IDX_SOURCE_SEGMENT_DAILY_FIELD" ON "PUBLIC"."SOURCE_SEGMENT_DAILY"("FIELD_ID" NULLS FIRST);
--;;
CREATE TABLE "PUBLIC"."SOURCE_METRIC_DAILY" COMMENT 'Daily source-scoped metric usage rollups'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Surrogate primary key' NOT NULL,
    "SOURCE_TYPE" CHARACTER VARYING(254) COMMENT 'Owning source kind for direct or projected facts, or null for canonical mixed facts',
    "SOURCE_ID" INTEGER COMMENT 'Owning table or card ID for direct or projected facts, or null for canonical mixed facts',
    "OWNERSHIP_MODE" CHARACTER VARYING(254) COMMENT 'Ownership attribution mode such as direct, projected, or mixed' NOT NULL,
    "AGG_TYPE" CHARACTER VARYING(254) COMMENT 'Aggregation operator for the metric fact' NOT NULL,
    "AGG_FIELD_ID" INTEGER COMMENT 'Aggregated field referenced by the metric fact when applicable',
    "TEMPORAL_FIELD_ID" INTEGER COMMENT 'Breakout field supplying temporal context for the metric fact when applicable',
    "TEMPORAL_UNIT" CHARACTER VARYING(254) COMMENT 'Temporal bucketing unit associated with the metric fact when applicable',
    "BUCKET_DATE" DATE COMMENT 'UTC day covered by the rollup row' NOT NULL,
    "COUNT" INTEGER COMMENT 'Number of observations for this fact on the bucket day' NOT NULL
);
--;;
ALTER TABLE "PUBLIC"."SOURCE_METRIC_DAILY" ADD CONSTRAINT "PUBLIC"."PK_SOURCE_METRIC_DAILY" PRIMARY KEY("ID");
--;;
CREATE INDEX "PUBLIC"."IDX_SOURCE_METRIC_DAILY_BUCKET_SOURCE" ON "PUBLIC"."SOURCE_METRIC_DAILY"("BUCKET_DATE" NULLS FIRST, "SOURCE_TYPE" NULLS FIRST, "SOURCE_ID" NULLS FIRST, "OWNERSHIP_MODE" NULLS FIRST);
--;;
CREATE INDEX "PUBLIC"."IDX_SOURCE_METRIC_DAILY_AGG" ON "PUBLIC"."SOURCE_METRIC_DAILY"("AGG_TYPE" NULLS FIRST, "AGG_FIELD_ID" NULLS FIRST);
--;;
CREATE TABLE "PUBLIC"."METABASE_FIELD"(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "CREATED_AT" TIMESTAMP WITH TIME ZONE NOT NULL,
    "UPDATED_AT" TIMESTAMP WITH TIME ZONE NOT NULL,
    "NAME" CHARACTER VARYING(254) NOT NULL,
    "BASE_TYPE" CHARACTER VARYING(255) NOT NULL,
    "SEMANTIC_TYPE" CHARACTER VARYING(255),
    "ACTIVE" BOOLEAN DEFAULT TRUE NOT NULL,
    "DESCRIPTION" CHARACTER LARGE OBJECT,
    "PREVIEW_DISPLAY" BOOLEAN DEFAULT TRUE NOT NULL,
    "POSITION" INTEGER DEFAULT 0 NOT NULL,
    "TABLE_ID" INTEGER NOT NULL,
    "PARENT_ID" INTEGER,
    "DISPLAY_NAME" CHARACTER VARYING(254),
    "VISIBILITY_TYPE" CHARACTER VARYING(32) DEFAULT 'normal' NOT NULL,
    "FK_TARGET_FIELD_ID" INTEGER,
    "LAST_ANALYZED" TIMESTAMP WITH TIME ZONE,
    "POINTS_OF_INTEREST" CHARACTER LARGE OBJECT,
    "CAVEATS" CHARACTER LARGE OBJECT,
    "FINGERPRINT" CHARACTER LARGE OBJECT COMMENT 'Serialized JSON containing non-identifying information about this Field, such as min, max, and percent JSON. Used for classification.',
    "FINGERPRINT_VERSION" INTEGER DEFAULT '0' COMMENT 'The version of the fingerprint for this Field. Used so we can keep track of which Fields need to be analyzed again when new things are added to fingerprints.' NOT NULL,
    "DATABASE_TYPE" CHARACTER LARGE OBJECT NOT NULL,
    "HAS_FIELD_VALUES" CHARACTER LARGE OBJECT COMMENT 'Whether we have FieldValues ("list"), should ad-hoc search ("search"), disable entirely ("none"), or infer dynamically (null)"',
    "SETTINGS" CHARACTER LARGE OBJECT COMMENT 'Serialized JSON FE-specific settings like formatting, etc. Scope of what is stored here may increase in future.',
    "DATABASE_POSITION" INTEGER DEFAULT 0 NOT NULL,
    "CUSTOM_POSITION" INTEGER DEFAULT 0 NOT NULL,
    "EFFECTIVE_TYPE" CHARACTER VARYING(255) COMMENT 'The effective type of the field after any coercions.',
    "COERCION_STRATEGY" CHARACTER VARYING(255) COMMENT 'A strategy to coerce the base_type into the effective_type.',
    "NFC_PATH" CHARACTER VARYING(254) COMMENT 'Nested field column paths, flattened',
    "DATABASE_REQUIRED" BOOLEAN DEFAULT FALSE COMMENT 'Indicates this field is required by the database for new records. Usually not null and without a default.' NOT NULL,
    "JSON_UNFOLDING" BOOLEAN DEFAULT FALSE COMMENT 'Enable/disable JSON unfolding for a field' NOT NULL,
    "DATABASE_IS_AUTO_INCREMENT" BOOLEAN DEFAULT FALSE COMMENT 'Indicates this field is auto incremented' NOT NULL,
    "DATABASE_INDEXED" BOOLEAN COMMENT 'If the database supports indexing, this column indicate whether or not a field is indexed, or is the 1st column in a composite index',
    "DATABASE_PARTITIONED" BOOLEAN COMMENT 'Whether the table is partitioned by this field',
    "IS_DEFECTIVE_DUPLICATE" BOOLEAN DEFAULT 'false' COMMENT 'Indicates whether column is a defective duplicate field that should never have been created.' NOT NULL,
    "UNIQUE_FIELD_HELPER" INTEGER GENERATED ALWAYS AS (CASE WHEN "IS_DEFECTIVE_DUPLICATE" = TRUE THEN NULL ELSE CASE WHEN "PARENT_ID" IS NULL THEN 0 ELSE "PARENT_ID" END END),
    "DATABASE_IS_PK" BOOLEAN COMMENT 'Whether or not the field is part of the primary key (not user editable like semantic_type)',
    "DATABASE_IS_NULLABLE" BOOLEAN COMMENT 'Whether or not the field will accept nulls',
    "DATABASE_IS_GENERATED" BOOLEAN COMMENT 'Whether or not the column is computed and will not accept writes',
    "DATABASE_DEFAULT" CHARACTER LARGE OBJECT COMMENT 'The dialect specific column default expression',
    "DIMENSION_INTERESTINGNESS" DOUBLE PRECISION COMMENT 'Interestingness score (0.0-1.0) for this field when treated as a dimension in a metric.'
);
--;;
ALTER TABLE "PUBLIC"."METABASE_FIELD" ADD CONSTRAINT "PUBLIC"."PK_METABASE_FIELD" PRIMARY KEY("ID");
--;;
CREATE INDEX "PUBLIC"."IDX_FIELD_TABLE_ID" ON "PUBLIC"."METABASE_FIELD"("TABLE_ID" NULLS FIRST);
--;;
CREATE INDEX "PUBLIC"."IDX_FIELD_PARENT_ID" ON "PUBLIC"."METABASE_FIELD"("PARENT_ID" NULLS FIRST);
--;;
CREATE INDEX "PUBLIC"."IDX_FIELD_FK_TARGET_FIELD_ID" ON "PUBLIC"."METABASE_FIELD"("FK_TARGET_FIELD_ID" NULLS FIRST);
--;;
