    "FIELD_ID" INTEGER COMMENT 'Breakout field referenced by the dimension fact' NOT NULL,
    "TEMPORAL_UNIT" CHARACTER VARYING(254) COMMENT 'Temporal bucketing unit for temporal breakouts when applicable',
    "BINNING" CHARACTER LARGE OBJECT COMMENT 'Canonical serialized binning configuration when applicable',
    "BUCKET_DATE" DATE COMMENT 'UTC day covered by the rollup row' NOT NULL,
    "COUNT" INTEGER COMMENT 'Number of observations for this fact on the bucket day' NOT NULL
);
