    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Surrogate primary key' NOT NULL,
    "SOURCE_TYPE" CHARACTER VARYING(254) COMMENT 'Owning source kind for the profiled dimension' NOT NULL,
    "SOURCE_ID" INTEGER COMMENT 'Owning table or card ID for the profiled dimension' NOT NULL,
    "FIELD_ID" INTEGER COMMENT 'Field being profiled' NOT NULL,
    "SOURCE_BASIS" CHARACTER VARYING(254) COMMENT 'Provenance of the profile signal such as fingerprint' NOT NULL,
    "OBSERVATION_TYPE" CHARACTER VARYING(254) COMMENT 'Kind of profile observation such as single-value or all-null' NOT NULL,
    "OBSERVATION_VALUE" CHARACTER LARGE OBJECT COMMENT 'Optional serialized value associated with the profile observation',
    "BUCKET_DATE" DATE COMMENT 'UTC day when the profile observation was recorded' NOT NULL,
    "COUNT" INTEGER COMMENT 'Number of times the observation was recorded on the bucket day' NOT NULL
);
