CREATE TABLE "PUBLIC"."SSO_RELAY_STATE" COMMENT 'Server-side store for SAML SSO RelayState context'(
    "ID" CHARACTER VARYING(128) COMMENT 'SHA-512 hash of the RelayState key' NOT NULL,
    "CONTINUE_URL" CHARACTER LARGE OBJECT COMMENT 'URL the popup falls back to when there is no opener window' NOT NULL,
    "ORIGIN" CHARACTER VARYING(254) COMMENT 'Origin used as the postMessage target when handing the session back to the opener (embedding only)',
    "EMBEDDING" BOOLEAN DEFAULT FALSE COMMENT 'Whether this is a modular-embedding popup login (postMessage handback) vs. a regular redirect login' NOT NULL,
    "EXPIRES_AT" TIMESTAMP WITH TIME ZONE COMMENT 'When this RelayState entry expires and is no longer valid' NOT NULL,
    "CREATED_AT" TIMESTAMP WITH TIME ZONE COMMENT 'When this RelayState entry was created' NOT NULL
);
