CREATE TABLE "PUBLIC"."TRANSFORM_RUN" COMMENT 'Table to track transform executions and their status in the app database'(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) COMMENT 'Unique ID' NOT NULL,
    "TRANSFORM_ID" INTEGER COMMENT 'Identifier for the transform',
    "RUN_METHOD" CHARACTER VARYING(255) COMMENT 'Method used to execute the transform job' NOT NULL,
    "STATUS" CHARACTER VARYING(50) COMMENT 'Current status of the transform job (running, completed, failed, etc.)' NOT NULL,
    "IS_ACTIVE" BOOLEAN COMMENT 'True only for currently running jobs, null for the others',
    "START_TIME" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'When the transform job started' NOT NULL,
    "END_TIME" TIMESTAMP WITH TIME ZONE COMMENT 'When the transform job completed (null if still running)',
    "MESSAGE" CHARACTER LARGE OBJECT COMMENT 'Human-readable message about the run; may contain error message in case status is error',
    "USER_ID" INTEGER COMMENT 'The user ID who triggered this run (owner for scheduled runs, current user for manual runs)',
    "TRANSFORM_NAME" CHARACTER VARYING(254) COMMENT 'Name of transform at time of run, stored for historical purposes',
    "TRANSFORM_ENTITY_ID" CHARACTER(21) COMMENT 'Original transform entity_id, stored for historical purposes',
    "CHECKPOINT_FILTER_FIELD_ID" INTEGER COMMENT 'The field ID used for incremental checkpoint filtering',
    "CHECKPOINT_LO_VALUE" CHARACTER LARGE OBJECT COMMENT 'The low checkpoint value for this run (exclusive lower bound)',
    "CHECKPOINT_HI_VALUE" CHARACTER LARGE OBJECT COMMENT 'The high checkpoint value for this run (inclusive upper bound)',
    "METERED_AS" CHARACTER VARYING(50) COMMENT 'The meter bucket this run counts toward (transform-basic, transform-advanced, or null)',
    "LAST_HEARTBEAT" TIMESTAMP WITH TIME ZONE DEFAULT LOCALTIMESTAMP COMMENT 'Heartbeat timestamp stamped periodically while the run executes; a stale value means the owning process died' NOT NULL,
    "JOB_RUN_ID" BIGINT COMMENT 'FK to transform_job_run; links each transform execution to its parent job run'
);
--;;
ALTER TABLE "PUBLIC"."TRANSFORM_RUN" ADD CONSTRAINT "PUBLIC"."PK_TRANSFORM_RUN" PRIMARY KEY("ID");
--;;
