CREATE VIEW "PUBLIC"."V_TASKS"("ID", "TASK", "STATUS", "DATABASE_QUALIFIED_ID", "STARTED_AT", "ENDED_AT", "DURATION_SECONDS", "DETAILS", "RUN_ID") AS
SELECT
    "ID",
    "TASK",
    "STATUS",
    'database_' || "DB_ID" AS "DATABASE_QUALIFIED_ID",
    "STARTED_AT",
    "ENDED_AT",
    CAST("DURATION" AS DOUBLE PRECISION) / 1000 AS "DURATION_SECONDS",
    "TASK_DETAILS" AS "DETAILS",
    "RUN_ID"
FROM "PUBLIC"."TASK_HISTORY";
--;;
CREATE VIEW "PUBLIC"."V_AUDIT_LOG"("ID", "TOPIC", "TIMESTAMP", "END_TIMESTAMP", "USER_ID", "ENTITY_TYPE", "ENTITY_ID", "ENTITY_QUALIFIED_ID", "DETAILS") AS
SELECT
    "ID",
    CASE WHEN "TOPIC" = 'card-create' THEN 'card-create' WHEN "TOPIC" = 'card-delete' THEN 'card-delete' WHEN "TOPIC" = 'card-update' THEN 'card-update' WHEN "TOPIC" = 'pulse-create' THEN 'subscription-create' WHEN "TOPIC" = 'pulse-delete' THEN 'subscription-delete' ELSE "TOPIC" END AS "TOPIC",
    "TIMESTAMP",
    NULL AS "END_TIMESTAMP",
    COALESCE("USER_ID", 0) AS "USER_ID",
    LOWER("MODEL") AS "ENTITY_TYPE",
    "MODEL_ID" AS "ENTITY_ID",
    CASE WHEN "MODEL" = 'Dataset' THEN CONCAT('card_', CAST("MODEL_ID" AS CHARACTER VARYING)) WHEN "MODEL_ID" IS NULL THEN NULL ELSE CONCAT(LOWER("MODEL"), '_', "MODEL_ID") END AS "ENTITY_QUALIFIED_ID",
    "DETAILS"
FROM "PUBLIC"."AUDIT_LOG"
WHERE "TOPIC" NOT IN('card-read', 'card-query', 'dashboard-read', 'dashboard-query');
--;;
CREATE VIEW "PUBLIC"."V_VIEW_LOG"("ID", "TIMESTAMP", "USER_ID", "ENTITY_TYPE", "ENTITY_ID", "ENTITY_QUALIFIED_ID", "EMBEDDING_CLIENT", "EMBEDDING_ROUTE", "IS_PREVIEW", "HAS_ACCESS", "CONTEXT", "EMBEDDING_SDK_VERSION", "METABASE_VERSION", "AUTH_METHOD", "TENANT_ID", "EMBEDDING_HOSTNAME", "EMBEDDING_PATH", "USER_AGENT", "SANITIZED_USER_AGENT", "IP_ADDRESS") AS
SELECT
    "ID",
    "TIMESTAMP",
    COALESCE("USER_ID", 0) AS "USER_ID",
    "MODEL" AS "ENTITY_TYPE",
    "MODEL_ID" AS "ENTITY_ID",
    "MODEL" || '_' || "MODEL_ID" AS "ENTITY_QUALIFIED_ID",
    "EMBEDDING_CLIENT",
    "EMBEDDING_ROUTE",
    CASE WHEN "EMBEDDING_CLIENT" LIKE '%-preview' THEN TRUE ELSE FALSE END AS "IS_PREVIEW",
    "HAS_ACCESS",
    "CONTEXT",
    "EMBEDDING_SDK_VERSION",
    "METABASE_VERSION",
    "AUTH_METHOD",
    "TENANT_ID",
    "EMBEDDING_HOSTNAME",
    "EMBEDDING_PATH",
    "USER_AGENT",
    "SANITIZED_USER_AGENT",
    "IP_ADDRESS"
FROM "PUBLIC"."VIEW_LOG";
--;;
CREATE VIEW "PUBLIC"."V_DASHBOARDCARD"("ENTITY_ID", "ENTITY_QUALIFIED_ID", "DASHBOARD_QUALIFIED_ID", "DASHBOARDTAB_ID", "CARD_QUALIFIED_ID", "CREATED_AT", "UPDATED_AT", "SIZE_X", "SIZE_Y", "VISUALIZATION_SETTINGS", "PARAMETER_MAPPINGS") AS
SELECT
    "ID" AS "ENTITY_ID",
    CONCAT('dashboardcard_', "ID") AS "ENTITY_QUALIFIED_ID",
    CONCAT('dashboard_', "DASHBOARD_ID") AS "DASHBOARD_QUALIFIED_ID",
    CONCAT('dashboardtab_', "DASHBOARD_TAB_ID") AS "DASHBOARDTAB_ID",
    CONCAT('card_', "CARD_ID") AS "CARD_QUALIFIED_ID",
    "CREATED_AT",
    "UPDATED_AT",
    "SIZE_X",
    "SIZE_Y",
    "VISUALIZATION_SETTINGS",
    "PARAMETER_MAPPINGS"
FROM "PUBLIC"."REPORT_DASHBOARDCARD";
--;;
CREATE VIEW "PUBLIC"."V_GROUP_MEMBERS"("USER_ID", "GROUP_ID", "GROUP_NAME") AS
(SELECT
    "USER_ID",
    "PERMISSIONS_GROUP"."ID" AS "GROUP_ID",
    "PERMISSIONS_GROUP"."NAME" AS "GROUP_NAME"
FROM "PUBLIC"."PERMISSIONS_GROUP_MEMBERSHIP"
LEFT OUTER JOIN "PUBLIC"."PERMISSIONS_GROUP"
    ON "PERMISSIONS_GROUP_MEMBERSHIP"."GROUP_ID" = "PERMISSIONS_GROUP"."ID")
UNION
(SELECT
    0 AS "USER_ID",
    0 AS "GROUP_ID",
    'Anonymous users' AS "GROUP_NAME");
--;;
CREATE VIEW "PUBLIC"."V_TASK_RUNS"("ID", "RUN_TYPE", "ENTITY_TYPE", "ENTITY_ID", "ENTITY_QUALIFIED_ID", "STARTED_AT", "ENDED_AT", "DURATION_SECONDS", "STATUS", "PROCESS_UUID", "UPDATED_AT") AS
SELECT
    "ID",
    "RUN_TYPE",
    "ENTITY_TYPE",
    "ENTITY_ID",
    CASE WHEN "ENTITY_TYPE" = 'database' THEN 'database_' || "ENTITY_ID" WHEN "ENTITY_TYPE" = 'card' THEN 'card_' || "ENTITY_ID" WHEN "ENTITY_TYPE" = 'dashboard' THEN 'dashboard_' || "ENTITY_ID" ELSE "ENTITY_TYPE" || '_' || "ENTITY_ID" END AS "ENTITY_QUALIFIED_ID",
    "STARTED_AT",
    "ENDED_AT",
    CASE WHEN "ENDED_AT" IS NOT NULL THEN CAST(DATEDIFF(SECOND, "STARTED_AT", "ENDED_AT") AS DOUBLE PRECISION) ELSE NULL END AS "DURATION_SECONDS",
    "STATUS",
    "PROCESS_UUID",
    "UPDATED_AT"
FROM "PUBLIC"."TASK_RUN";
--;;
CREATE VIEW "PUBLIC"."V_QUERY_LOG"("ENTITY_ID", "STARTED_AT", "RUNNING_TIME_SECONDS", "RESULT_ROWS", "IS_NATIVE", "QUERY_SOURCE", "ERROR", "USER_ID", "CARD_ID", "CARD_QUALIFIED_ID", "DASHBOARD_ID", "DASHBOARD_QUALIFIED_ID", "PULSE_ID", "DATABASE_ID", "DATABASE_QUALIFIED_ID", "CACHE_HIT", "ACTION_ID", "ACTION_QUALIFIED_ID", "TRANSFORM_ID", "TRANSFORM_QUALIFIED_ID", "LENS_ID", "LENS_PARAMS", "QUERY", "EMBEDDING_CLIENT", "EMBEDDING_ROUTE", "IS_PREVIEW", "EMBEDDING_SDK_VERSION", "METABASE_VERSION", "AUTH_METHOD", "IS_SANDBOXED", "IS_IMPERSONATED", "IS_DB_ROUTED", "PARAMETERS", "TENANT_ID", "EMBEDDING_HOSTNAME", "EMBEDDING_PATH", "USER_AGENT", "SANITIZED_USER_AGENT", "IP_ADDRESS") AS
SELECT
    "ID" AS "ENTITY_ID",
    "STARTED_AT",
    CAST("RUNNING_TIME" AS DOUBLE PRECISION) / 1000 AS "RUNNING_TIME_SECONDS",
    "RESULT_ROWS",
    "NATIVE" AS "IS_NATIVE",
    "CONTEXT" AS "QUERY_SOURCE",
    "ERROR",
    COALESCE("EXECUTOR_ID", 0) AS "USER_ID",
    "CARD_ID",
    'card_' || "CARD_ID" AS "CARD_QUALIFIED_ID",
    "DASHBOARD_ID",
    'dashboard_' || "DASHBOARD_ID" AS "DASHBOARD_QUALIFIED_ID",
    "PULSE_ID",
    "DATABASE_ID",
    'database_' || "DATABASE_ID" AS "DATABASE_QUALIFIED_ID",
    "CACHE_HIT",
    "ACTION_ID",
    'action_' || "ACTION_ID" AS "ACTION_QUALIFIED_ID",
    "TRANSFORM_ID",
    'transform_' || "TRANSFORM_ID" AS "TRANSFORM_QUALIFIED_ID",
    "LENS_ID",
    "LENS_PARAMS",
    "QUERY",
    "EMBEDDING_CLIENT",
    "EMBEDDING_ROUTE",
    CASE WHEN "EMBEDDING_CLIENT" LIKE '%-preview' THEN TRUE ELSE FALSE END AS "IS_PREVIEW",
    "EMBEDDING_SDK_VERSION",
    "METABASE_VERSION",
    "AUTH_METHOD",
    "IS_SANDBOXED",
    "IS_IMPERSONATED",
    "IS_DB_ROUTED",
    "PARAMETERS",
    "TENANT_ID",
    "EMBEDDING_HOSTNAME",
    "EMBEDDING_PATH",
    "USER_AGENT",
    "SANITIZED_USER_AGENT",
    "IP_ADDRESS"
FROM "PUBLIC"."QUERY_EXECUTION"
LEFT OUTER JOIN "PUBLIC"."QUERY"
    ON "QUERY_EXECUTION"."HASH" = "QUERY"."QUERY_HASH";
--;;
CREATE VIEW "PUBLIC"."V_CONTENT"("ENTITY_ID", "ENTITY_QUALIFIED_ID", "ENTITY_TYPE", "CREATED_AT", "UPDATED_AT", "CREATOR_ID", "NAME", "DESCRIPTION", "COLLECTION_ID", "MADE_PUBLIC_BY_USER", "IS_EMBEDDING_ENABLED", "IS_VERIFIED", "ARCHIVED", "ACTION_TYPE", "ACTION_MODEL_ID", "COLLECTION_IS_OFFICIAL", "COLLECTION_IS_PERSONAL", "QUESTION_VIZ_TYPE", "QUESTION_DATABASE_ID", "QUESTION_IS_NATIVE", "EVENT_TIMESTAMP") AS
(((((((SELECT
    "ACTION"."ID" AS "ENTITY_ID",
    'action_' || "ACTION"."ID" AS "ENTITY_QUALIFIED_ID",
    'action' AS "ENTITY_TYPE",
    "CREATED_AT",
    "UPDATED_AT",
    "CREATOR_ID",
    "NAME",
    "DESCRIPTION",
    CAST(NULL AS INTEGER) AS "COLLECTION_ID",
    "MADE_PUBLIC_BY_ID" AS "MADE_PUBLIC_BY_USER",
    UNKNOWN AS "IS_EMBEDDING_ENABLED",
    UNKNOWN AS "IS_VERIFIED",
    "ARCHIVED",
    "TYPE" AS "ACTION_TYPE",
    "MODEL_ID" AS "ACTION_MODEL_ID",
    NULL AS "COLLECTION_IS_OFFICIAL",
    NULL AS "COLLECTION_IS_PERSONAL",
    NULL AS "QUESTION_VIZ_TYPE",
    NULL AS "QUESTION_DATABASE_ID",
    UNKNOWN AS "QUESTION_IS_NATIVE",
    CAST(NULL AS TIMESTAMP) AS "EVENT_TIMESTAMP"
FROM "PUBLIC"."ACTION")
UNION
(SELECT
    "COLLECTION"."ID" AS "ENTITY_ID",
    'collection_' || "COLLECTION"."ID" AS "ENTITY_QUALIFIED_ID",
    'collection' AS "ENTITY_TYPE",
    "CREATED_AT",
    NULL AS "UPDATED_AT",
    NULL AS "CREATOR_ID",
    "NAME",
    "DESCRIPTION",
    NULL AS "COLLECTION_ID",
    NULL AS "MADE_PUBLIC_BY_USER",
    NULL AS "IS_EMBEDDING_ENABLED",
    UNKNOWN AS "IS_VERIFIED",
    "ARCHIVED",
    NULL AS "ACTION_TYPE",
    NULL AS "ACTION_MODEL_ID",
    CASE WHEN "AUTHORITY_LEVEL" = 'official' THEN TRUE ELSE FALSE END AS "COLLECTION_IS_OFFICIAL",
    CASE WHEN "PERSONAL_OWNER_ID" IS NOT NULL THEN TRUE ELSE FALSE END AS "COLLECTION_IS_PERSONAL",
    NULL AS "QUESTION_VIZ_TYPE",
    NULL AS "QUESTION_DATABASE_ID",
    NULL AS "QUESTION_IS_NATIVE",
    NULL AS "EVENT_TIMESTAMP"
FROM "PUBLIC"."COLLECTION"))
UNION
(SELECT
    "REPORT_CARD"."ID" AS "ENTITY_ID",
    'card_' || "REPORT_CARD"."ID" AS "ENTITY_QUALIFIED_ID",
    "TYPE" AS "ENTITY_TYPE",
    "CREATED_AT",
    "UPDATED_AT",
    "CREATOR_ID",
    "NAME",
    "DESCRIPTION",
    "COLLECTION_ID" AS "COLLECTION_ID",
    "MADE_PUBLIC_BY_ID" AS "MADE_PUBLIC_BY_USER",
    "ENABLE_EMBEDDING" AS "IS_EMBEDDING_ENABLED",
    CASE WHEN "IS_VERIFIED" THEN TRUE ELSE FALSE END AS "IS_VERIFIED",
    "ARCHIVED",
    NULL AS "ACTION_TYPE",
    NULL AS "ACTION_MODEL_ID",
    NULL AS "COLLECTION_IS_OFFICIAL",
    NULL AS "COLLECTION_IS_PERSONAL",
    "DISPLAY" AS "QUESTION_VIZ_TYPE",
    'database_' || "DATABASE_ID" AS "QUESTION_DATABASE_ID",
    CASE WHEN "QUERY_TYPE" = 'native' THEN TRUE ELSE FALSE END AS "QUESTION_IS_NATIVE",
    NULL AS "EVENT_TIMESTAMP"
FROM "PUBLIC"."REPORT_CARD"
LEFT OUTER JOIN (
    SELECT
        "MODERATED_ITEM_TYPE" || '_' || "MODERATED_ITEM_ID" AS "ENTITY_QUALIFIED_ID",
        CASE WHEN "STATUS" = 'verified' THEN TRUE ELSE FALSE END AS "IS_VERIFIED"
    FROM "PUBLIC"."MODERATION_REVIEW"
    WHERE "MOST_RECENT"
) "MODERATION"
    ON ('card_' || "REPORT_CARD"."ID") = "MODERATION"."ENTITY_QUALIFIED_ID"))
UNION
(SELECT
    "REPORT_DASHBOARD"."ID" AS "ENTITY_ID",
    'dashboard_' || "REPORT_DASHBOARD"."ID" AS "ENTITY_QUALIFIED_ID",
    'dashboard' AS "ENTITY_TYPE",
    "CREATED_AT",
    "UPDATED_AT",
    "CREATOR_ID",
    "NAME",
    "DESCRIPTION",
    "COLLECTION_ID" AS "COLLECTION_ID",
    "MADE_PUBLIC_BY_ID" AS "MADE_PUBLIC_BY_USER",
    "ENABLE_EMBEDDING" AS "IS_EMBEDDING_ENABLED",
    CASE WHEN "IS_VERIFIED" THEN TRUE ELSE FALSE END AS "IS_VERIFIED",
    "ARCHIVED",
    NULL AS "ACTION_TYPE",
    NULL AS "ACTION_MODEL_ID",
    NULL AS "COLLECTION_IS_OFFICIAL",
    NULL AS "COLLECTION_IS_PERSONAL",
    NULL AS "QUESTION_VIZ_TYPE",
    NULL AS "QUESTION_DATABASE_ID",
    NULL AS "QUESTION_IS_NATIVE",
    NULL AS "EVENT_TIMESTAMP"
FROM "PUBLIC"."REPORT_DASHBOARD"
LEFT OUTER JOIN (
    SELECT
        "MODERATED_ITEM_TYPE" || '_' || "MODERATED_ITEM_ID" AS "ENTITY_QUALIFIED_ID",
        CASE WHEN "STATUS" = 'verified' THEN TRUE ELSE FALSE END AS "IS_VERIFIED"
    FROM "PUBLIC"."MODERATION_REVIEW"
    WHERE "MOST_RECENT"
) "MODERATION"
    ON ('dashboard_' || "REPORT_DASHBOARD"."ID") = "MODERATION"."ENTITY_QUALIFIED_ID"))
UNION
(SELECT
    "DOCUMENT"."ID" AS "ENTITY_ID",
    'document_' || "DOCUMENT"."ID" AS "ENTITY_QUALIFIED_ID",
    'document' AS "ENTITY_TYPE",
    "CREATED_AT",
    "UPDATED_AT",
    "CREATOR_ID",
    "NAME",
    CAST(NULL AS CHARACTER VARYING) AS "DESCRIPTION",
    "COLLECTION_ID" AS "COLLECTION_ID",
    CAST(NULL AS INTEGER) AS "MADE_PUBLIC_BY_USER",
    UNKNOWN AS "IS_EMBEDDING_ENABLED",
    UNKNOWN AS "IS_VERIFIED",
    "ARCHIVED",
    NULL AS "ACTION_TYPE",
    CAST(NULL AS INTEGER) AS "ACTION_MODEL_ID",
    NULL AS "COLLECTION_IS_OFFICIAL",
    NULL AS "COLLECTION_IS_PERSONAL",
    NULL AS "QUESTION_VIZ_TYPE",
    NULL AS "QUESTION_DATABASE_ID",
    UNKNOWN AS "QUESTION_IS_NATIVE",
    CAST(NULL AS TIMESTAMP) AS "EVENT_TIMESTAMP"
FROM "PUBLIC"."DOCUMENT"))
UNION
(SELECT
    "EVENT"."ID" AS "ENTITY_ID",
    'event_' || "EVENT"."ID" AS "ENTITY_QUALIFIED_ID",
    'event' AS "ENTITY_TYPE",
    "EVENT"."CREATED_AT",
    "EVENT"."UPDATED_AT",
    "EVENT"."CREATOR_ID",
    "EVENT"."NAME",
    "EVENT"."DESCRIPTION",
    "TIMELINE"."COLLECTION_ID",
    NULL AS "MADE_PUBLIC_BY_USER",
    NULL AS "IS_EMBEDDING_ENABLED",
    UNKNOWN AS "IS_VERIFIED",
    "EVENT"."ARCHIVED",
    NULL AS "ACTION_TYPE",
    NULL AS "ACTION_MODEL_ID",
    NULL AS "COLLECTION_IS_OFFICIAL",
    NULL AS "COLLECTION_IS_PERSONAL",
    NULL AS "QUESTION_VIZ_TYPE",
    NULL AS "QUESTION_DATABASE_ID",
    NULL AS "QUESTION_IS_NATIVE",
    "TIMESTAMP" AS "EVENT_TIMESTAMP"
FROM "PUBLIC"."TIMELINE_EVENT" "EVENT"
LEFT OUTER JOIN "PUBLIC"."TIMELINE"
    ON "EVENT"."TIMELINE_ID" = "TIMELINE"."ID"))
UNION
(SELECT
    "TRANSFORM"."ID" AS "ENTITY_ID",
    'transform_' || "TRANSFORM"."ID" AS "ENTITY_QUALIFIED_ID",
    'transform' AS "ENTITY_TYPE",
    "CREATED_AT",
    "UPDATED_AT",
    "CREATOR_ID",
    "NAME",
    "DESCRIPTION",
    CAST(NULL AS INTEGER) AS "COLLECTION_ID",
    CAST(NULL AS INTEGER) AS "MADE_PUBLIC_BY_USER",
    UNKNOWN AS "IS_EMBEDDING_ENABLED",
    UNKNOWN AS "IS_VERIFIED",
    FALSE AS "ARCHIVED",
    NULL AS "ACTION_TYPE",
    CAST(NULL AS INTEGER) AS "ACTION_MODEL_ID",
    NULL AS "COLLECTION_IS_OFFICIAL",
    NULL AS "COLLECTION_IS_PERSONAL",
    NULL AS "QUESTION_VIZ_TYPE",
    NULL AS "QUESTION_DATABASE_ID",
    UNKNOWN AS "QUESTION_IS_NATIVE",
    CAST(NULL AS TIMESTAMP) AS "EVENT_TIMESTAMP"
FROM "PUBLIC"."TRANSFORM"))
UNION
(SELECT
    "GLOSSARY"."ID" AS "ENTITY_ID",
    'glossary_' || "GLOSSARY"."ID" AS "ENTITY_QUALIFIED_ID",
    'glossary' AS "ENTITY_TYPE",
    "CREATED_AT",
    "UPDATED_AT",
    "CREATOR_ID",
    "TERM" AS "NAME",
    "DEFINITION" AS "DESCRIPTION",
    CAST(NULL AS INTEGER) AS "COLLECTION_ID",
    CAST(NULL AS INTEGER) AS "MADE_PUBLIC_BY_USER",
    UNKNOWN AS "IS_EMBEDDING_ENABLED",
    UNKNOWN AS "IS_VERIFIED",
    FALSE AS "ARCHIVED",
    NULL AS "ACTION_TYPE",
    CAST(NULL AS INTEGER) AS "ACTION_MODEL_ID",
    NULL AS "COLLECTION_IS_OFFICIAL",
    NULL AS "COLLECTION_IS_PERSONAL",
    NULL AS "QUESTION_VIZ_TYPE",
    NULL AS "QUESTION_DATABASE_ID",
    UNKNOWN AS "QUESTION_IS_NATIVE",
    CAST(NULL AS TIMESTAMP) AS "EVENT_TIMESTAMP"
FROM "PUBLIC"."GLOSSARY");
--;;
CREATE VIEW "PUBLIC"."V_SUBSCRIPTIONS"("ENTITY_ID", "ENTITY_QUALIFIED_ID", "CREATED_AT", "UPDATED_AT", "CREATOR_ID", "ARCHIVED", "DASHBOARD_QUALIFIED_ID", "SCHEDULE_TYPE", "SCHEDULE_DAY", "SCHEDULE_HOUR", "RECIPIENT_TYPE", "RECIPIENTS", "RECIPIENT_EXTERNAL", "PARAMETERS") AS
SELECT
    "PULSE"."ID" AS "ENTITY_ID",
    'pulse_' || "PULSE"."ID" AS "ENTITY_QUALIFIED_ID",
    "PULSE"."CREATED_AT",
    "PULSE"."UPDATED_AT",
    "CREATOR_ID",
    "ARCHIVED",
    'dashboard_' || "DASHBOARD_ID" AS "DASHBOARD_QUALIFIED_ID",
    "PULSE_CHANNEL"."SCHEDULE_TYPE",
    "PULSE_CHANNEL"."SCHEDULE_DAY",
    "PULSE_CHANNEL"."SCHEDULE_HOUR",
    "CHANNEL_TYPE" AS "RECIPIENT_TYPE",
    NULL AS "RECIPIENTS",
    "DETAILS" AS "RECIPIENT_EXTERNAL",
    "PARAMETERS"
FROM "PUBLIC"."PULSE"
LEFT OUTER JOIN "PUBLIC"."PULSE_CHANNEL"
    ON "PULSE"."ID" = "PULSE_CHANNEL"."PULSE_ID"
WHERE "ALERT_CONDITION" IS NULL;
--;;
CREATE VIEW "PUBLIC"."V_USERS"("USER_ID", "ENTITY_QUALIFIED_ID", "TYPE", "EMAIL", "FIRST_NAME", "LAST_NAME", "FULL_NAME", "DATE_JOINED", "LAST_LOGIN", "UPDATED_AT", "IS_ADMIN", "IS_ACTIVE", "SSO_SOURCE", "LOCALE", "TENANT_ID", "TENANT_QUALIFIED_ID") AS
(SELECT
    "ID" AS "USER_ID",
    'user_' || "ID" AS "ENTITY_QUALIFIED_ID",
    "TYPE",
    CASE WHEN "TYPE" = 'api-key' THEN NULL ELSE "EMAIL" END AS "EMAIL",
    "FIRST_NAME",
    "LAST_NAME",
    COALESCE("FIRST_NAME" || ' ' || "LAST_NAME", "FIRST_NAME", "LAST_NAME") AS "FULL_NAME",
    "DATE_JOINED",
    "LAST_LOGIN",
    "UPDATED_AT",
    "IS_SUPERUSER" AS "IS_ADMIN",
    "IS_ACTIVE",
    "SSO_SOURCE",
    "LOCALE",
    "TENANT_ID",
    'tenant_' || "TENANT_ID" AS "TENANT_QUALIFIED_ID"
FROM "PUBLIC"."CORE_USER")
UNION
(SELECT
    0 AS "USER_ID",
    'user_0' AS "ENTITY_QUALIFIED_ID",
    'anonymous' AS "TYPE",
    NULL AS "EMAIL",
    'External' AS "FIRST_NAME",
    'User' AS "LAST_NAME",
    'External User' AS "FULL_NAME",
    NULL AS "DATE_JOINED",
    NULL AS "LAST_LOGIN",
    NULL AS "UPDATED_AT",
    FALSE AS "IS_ADMIN",
    NULL AS "IS_ACTIVE",
    NULL AS "SSO_SOURCE",
    NULL AS "LOCALE",
    NULL AS "TENANT_ID",
    NULL AS "TENANT_QUALIFIED_ID");
--;;
CREATE VIEW "PUBLIC"."V_ALERTS"("ENTITY_ID", "ENTITY_QUALIFIED_ID", "CREATED_AT", "UPDATED_AT", "CREATOR_ID", "CARD_ID", "CARD_QUALIFIED_ID", "ALERT_CONDITION", "SCHEDULE_TYPE", "SCHEDULE_DAY", "SCHEDULE_HOUR", "ARCHIVED", "RECIPIENT_TYPE", "RECIPIENTS", "RECIPIENT_EXTERNAL") AS
SELECT
    "N"."ID" AS "ENTITY_ID",
    'notification_' || "N"."ID" AS "ENTITY_QUALIFIED_ID",
    "N"."CREATED_AT",
    "N"."UPDATED_AT",
    "N"."CREATOR_ID",
    "NC"."CARD_ID",
    'card_' || "NC"."CARD_ID" AS "CARD_QUALIFIED_ID",
    CASE WHEN "NC"."SEND_CONDITION" = 'has_result' THEN 'rows' WHEN "NC"."SEND_CONDITION" IN('goal_above', 'goal_below') THEN 'goal' END AS "ALERT_CONDITION",
    CASE WHEN "NS"."UI_DISPLAY_TYPE" = 'cron/raw' THEN 'custom' WHEN (REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ ([^ ]+)', 1, 1, '', 1) = '*')
        OR REGEXP_LIKE(REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ ([^ ]+)', 1, 1, '', 1), '^[0-9]+/[0-9]+$') THEN 'by the minute' WHEN (REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1) <> '*')
        AND ((REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ [^ ]+ [^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1) = '?')
        OR REGEXP_LIKE(REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ [^ ]+ [^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1), '^[0-9]#1$')
        OR REGEXP_LIKE(REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ [^ ]+ [^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1), '^[0-9]L$')) THEN 'monthly' WHEN (REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ [^ ]+ [^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1) <> '?')
        AND (REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ [^ ]+ [^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1) <> '*') THEN 'weekly' WHEN REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1) <> '*' THEN 'daily' ELSE 'hourly' END AS "SCHEDULE_TYPE",
    CASE WHEN REGEXP_LIKE(REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ [^ ]+ [^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1), '^1') THEN 'sun' WHEN REGEXP_LIKE(REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ [^ ]+ [^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1), '^2') THEN 'mon' WHEN REGEXP_LIKE(REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ [^ ]+ [^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1), '^3') THEN 'tue' WHEN REGEXP_LIKE(REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ [^ ]+ [^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1), '^4') THEN 'wed' WHEN REGEXP_LIKE(REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ [^ ]+ [^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1), '^5') THEN 'thu' WHEN REGEXP_LIKE(REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ [^ ]+ [^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1), '^6') THEN 'fri' WHEN REGEXP_LIKE(REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ [^ ]+ [^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1), '^7') THEN 'sat' ELSE NULL END AS "SCHEDULE_DAY",
    CASE WHEN REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1) = '*' THEN NULL WHEN REGEXP_LIKE(REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1), '^[0-9]+$') THEN CAST(REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1) AS INTEGER) WHEN REGEXP_LIKE(REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1), '^[0-9]+/[0-9]+$') THEN CAST(REGEXP_SUBSTR(REGEXP_SUBSTR("NS"."CRON_SCHEDULE", '^[^ ]+ [^ ]+ ([^ ]+)', 1, 1, '', 1), '^([0-9]+)/[0-9]+$', 1, 1, '', 1) AS INTEGER) ELSE NULL END AS "SCHEDULE_HOUR",
    "N"."ACTIVE" = FALSE AS "ARCHIVED",
    "NH"."CHANNEL_TYPE" AS "RECIPIENT_TYPE",
    (SELECT
        LISTAGG("CU"."EMAIL") WITHIN GROUP (ORDER BY NULL)
    FROM "PUBLIC"."NOTIFICATION_RECIPIENT" "NR"
    LEFT OUTER JOIN "PUBLIC"."CORE_USER" "CU"
        ON ("NR"."TYPE" = 'notification-recipient/user')
        AND ("NR"."USER_ID" = "CU"."ID")
    WHERE "NR"."NOTIFICATION_HANDLER_ID" = "NH"."ID") AS "RECIPIENTS",
    (SELECT
        LISTAGG("NR"."DETAILS") WITHIN GROUP (ORDER BY NULL)
    FROM "PUBLIC"."NOTIFICATION_RECIPIENT" "NR"
    WHERE ("NR"."TYPE" = 'notification-recipient/raw-value')
        AND ("NR"."NOTIFICATION_HANDLER_ID" = "NH"."ID")) AS "RECIPIENT_EXTERNAL"
FROM "PUBLIC"."NOTIFICATION" "N"
INNER JOIN "PUBLIC"."NOTIFICATION_CARD" "NC"
    ON 1=1
INNER JOIN "PUBLIC"."NOTIFICATION_SUBSCRIPTION" "NS"
    ON 1=1
LEFT OUTER JOIN "PUBLIC"."NOTIFICATION_HANDLER" "NH"
    ON "N"."ID" = "NH"."NOTIFICATION_ID"
WHERE ("N"."PAYLOAD_TYPE" = 'notification/card')
    AND ("NS"."TYPE" = 'notification-subscription/cron')
    AND ("N"."PAYLOAD_ID" = "NC"."ID")
    AND ("N"."ID" = "NS"."NOTIFICATION_ID");
--;;
CREATE VIEW "PUBLIC"."V_DATABASES"("ENTITY_ID", "ENTITY_QUALIFIED_ID", "CREATED_AT", "UPDATED_AT", "NAME", "DESCRIPTION", "DATABASE_TYPE", "METADATA_SYNC_SCHEDULE", "CACHE_FIELD_VALUES_SCHEDULE", "TIMEZONE", "IS_ON_DEMAND", "AUTO_RUN_QUERIES", "CACHE_TTL", "CREATOR_ID", "DB_VERSION") AS
SELECT
    "ID" AS "ENTITY_ID",
    CONCAT('database_', "ID") AS "ENTITY_QUALIFIED_ID",
    "CREATED_AT",
    "UPDATED_AT",
    "NAME",
    "DESCRIPTION",
    "ENGINE" AS "DATABASE_TYPE",
    "METADATA_SYNC_SCHEDULE",
    "CACHE_FIELD_VALUES_SCHEDULE",
    "TIMEZONE",
    "IS_ON_DEMAND",
    "AUTO_RUN_QUERIES",
    "CACHE_TTL",
    "CREATOR_ID",
    "DBMS_VERSION" AS "DB_VERSION"
FROM "PUBLIC"."METABASE_DATABASE"
WHERE "ID" <> 13371337;
--;;
CREATE VIEW "PUBLIC"."V_FIELDS"("ENTITY_ID", "ENTITY_QUALIFIED_ID", "CREATED_AT", "UPDATED_AT", "NAME", "DISPLAY_NAME", "DESCRIPTION", "BASE_TYPE", "VISIBILITY_TYPE", "FK_TARGET_FIELD_ID", "HAS_FIELD_VALUES", "ACTIVE", "TABLE_ID") AS
SELECT
    "ID" AS "ENTITY_ID",
    'field_' || "ID" AS "ENTITY_QUALIFIED_ID",
    "CREATED_AT",
    "UPDATED_AT",
    "NAME",
    "DISPLAY_NAME",
    "DESCRIPTION",
    "BASE_TYPE",
    "VISIBILITY_TYPE",
    "FK_TARGET_FIELD_ID",
    "HAS_FIELD_VALUES",
    "ACTIVE",
    "TABLE_ID" AS "TABLE_ID"
FROM "PUBLIC"."METABASE_FIELD";
--;;
CREATE VIEW "PUBLIC"."V_TABLES"("ENTITY_ID", "ENTITY_QUALIFIED_ID", "CREATED_AT", "UPDATED_AT", "NAME", "DISPLAY_NAME", "DESCRIPTION", "ACTIVE", "DATABASE_ID", "SCHEMA", "IS_UPLOAD", "ENTITY_TYPE", "VISIBILITY_TYPE", "ESTIMATED_ROW_COUNT", "VIEW_COUNT", "OWNER_EMAIL", "OWNER_USER_ID") AS
SELECT
    "ID" AS "ENTITY_ID",
    'table_' || "ID" AS "ENTITY_QUALIFIED_ID",
    "CREATED_AT",
    "UPDATED_AT",
    "NAME",
    "DISPLAY_NAME",
    "DESCRIPTION",
    "ACTIVE",
    "DB_ID" AS "DATABASE_ID",
    "SCHEMA",
    "IS_UPLOAD",
    "ENTITY_TYPE",
    "VISIBILITY_TYPE",
    "ESTIMATED_ROW_COUNT",
    "VIEW_COUNT",
    "OWNER_EMAIL",
    "OWNER_USER_ID"
FROM "PUBLIC"."METABASE_TABLE";
--;;
CREATE VIEW "PUBLIC"."V_AI_USAGE_LOG"("USAGE_LOG_ID", "CREATED_AT", "SOURCE", "SOURCE_NAME", "MODEL", "PROFILE_ID", "PROMPT_TOKENS", "COMPLETION_TOKENS", "TOTAL_TOKENS", "CONVERSATION_ID", "USER_ID", "USER_QUALIFIED_ID", "USER_DISPLAY_NAME", "GROUP_NAME", "IP_ADDRESS", "EMBEDDING_HOSTNAME", "EMBEDDING_PATH", "USER_AGENT", "SANITIZED_USER_AGENT", "TENANT_ID", "REQUEST_ID", "CACHE_CREATION_TOKENS", "CACHE_READ_TOKENS") AS
SELECT
    "A"."ID" AS "USAGE_LOG_ID",
    "A"."CREATED_AT",
    "A"."SOURCE",
    CASE "A"."SOURCE" WHEN 'metabot_agent' THEN 'Metabot' WHEN 'agent' THEN 'Metabot' WHEN 'document_generate_content' THEN 'Documents' WHEN 'example_question_generation_batch' THEN 'Suggested Prompts' WHEN 'slack' THEN 'Slackbot' WHEN 'slackbot' THEN 'Slackbot' WHEN 'oss-sql-gen' THEN 'SQL' WHEN 'sql-gen' THEN 'SQL' WHEN 'unknown' THEN 'Unknown' ELSE "A"."SOURCE" END AS "SOURCE_NAME",
    "A"."MODEL",
    "A"."PROFILE_ID",
    "A"."PROMPT_TOKENS",
    "A"."COMPLETION_TOKENS",
    "A"."TOTAL_TOKENS",
    "A"."CONVERSATION_ID",
    "A"."USER_ID",
    'user_' || "A"."USER_ID" AS "USER_QUALIFIED_ID",
    COALESCE("U"."FIRST_NAME" || ' ' || "U"."LAST_NAME", "U"."EMAIL") AS "USER_DISPLAY_NAME",
    (SELECT
        "PG"."NAME"
    FROM "PUBLIC"."PERMISSIONS_GROUP_MEMBERSHIP" "PGM"
    INNER JOIN "PUBLIC"."PERMISSIONS_GROUP" "PG"
        ON 1=1
    WHERE ("PGM"."USER_ID" = "A"."USER_ID")
        AND ("PG"."ID" <> 1)
        AND ("PG"."ID" = "PGM"."GROUP_ID")
    ORDER BY 1
    FETCH FIRST ROW ONLY) AS "GROUP_NAME",
    "C"."IP_ADDRESS" AS "IP_ADDRESS",
    "C"."EMBEDDING_HOSTNAME" AS "EMBEDDING_HOSTNAME",
    "C"."EMBEDDING_PATH" AS "EMBEDDING_PATH",
    "C"."USER_AGENT" AS "USER_AGENT",
    "C"."SANITIZED_USER_AGENT" AS "SANITIZED_USER_AGENT",
    "A"."TENANT_ID",
    "A"."REQUEST_ID",
    "A"."CACHE_CREATION_TOKENS",
    "A"."CACHE_READ_TOKENS"
FROM "PUBLIC"."AI_USAGE_LOG" "A"
LEFT OUTER JOIN "PUBLIC"."CORE_USER" "U"
    ON "U"."ID" = "A"."USER_ID"
LEFT OUTER JOIN "PUBLIC"."METABOT_CONVERSATION" "C"
    ON "C"."ID" = "A"."CONVERSATION_ID";
--;;
CREATE VIEW "PUBLIC"."V_METABOT_CONVERSATIONS"("CONVERSATION_ID", "CREATED_AT", "USER_ID", "SUMMARY", "USER_DISPLAY_NAME", "MESSAGE_COUNT", "USER_MESSAGE_COUNT", "ASSISTANT_MESSAGE_COUNT", "TOTAL_TOKENS", "PROMPT_TOKENS", "COMPLETION_TOKENS", "LAST_MESSAGE_AT", "PROFILE_ID", "PROFILE_NAME", "GROUP_NAME", "SOURCE", "SOURCE_NAME", "IP_ADDRESS", "EMBEDDING_HOSTNAME", "EMBEDDING_PATH", "USER_AGENT", "SANITIZED_USER_AGENT", "TENANT_ID", "TENANT_NAME", "MODEL") AS
SELECT
    "C"."ID" AS "CONVERSATION_ID",
    "C"."CREATED_AT",
    "C"."USER_ID",
    "C"."SUMMARY",
    COALESCE("U"."FIRST_NAME" || ' ' || "U"."LAST_NAME", "U"."EMAIL") AS "USER_DISPLAY_NAME",
    COUNT("M"."ID") AS "MESSAGE_COUNT",
    COUNT(CASE WHEN "M"."ROLE" = 'user' THEN 1 END) AS "USER_MESSAGE_COUNT",
    COUNT(CASE WHEN "M"."ROLE" = 'assistant' THEN 1 END) AS "ASSISTANT_MESSAGE_COUNT",
    COALESCE(MAX("A"."TOTAL_TOKENS"), 0) AS "TOTAL_TOKENS",
    COALESCE(MAX("A"."PROMPT_TOKENS"), 0) AS "PROMPT_TOKENS",
    COALESCE(MAX("A"."COMPLETION_TOKENS"), 0) AS "COMPLETION_TOKENS",
    MAX("M"."CREATED_AT") AS "LAST_MESSAGE_AT",
    (SELECT
        "MM"."PROFILE_ID"
    FROM "PUBLIC"."METABOT_MESSAGE" "MM"
    WHERE ("MM"."CONVERSATION_ID" = "C"."ID")
        AND ("MM"."DELETED_AT" IS NULL)
        AND ("MM"."ROLE" = 'assistant')
    ORDER BY "MM"."CREATED_AT", "MM"."ID"
    FETCH FIRST ROW ONLY) AS "PROFILE_ID",
    (SELECT
        CASE "MM"."PROFILE_ID" WHEN 'internal' THEN 'Internal' WHEN 'embedding_next' THEN 'Embedding' WHEN 'nlq' THEN 'NLQ' WHEN 'sql' THEN 'SQL' WHEN 'slackbot' THEN 'Slackbot' WHEN 'transforms_codegen' THEN 'Transforms codegen' WHEN 'document-generate-content' THEN 'Documents' ELSE "MM"."PROFILE_ID" END
    FROM "PUBLIC"."METABOT_MESSAGE" "MM"
    WHERE ("MM"."CONVERSATION_ID" = "C"."ID")
        AND ("MM"."DELETED_AT" IS NULL)
        AND ("MM"."ROLE" = 'assistant')
    ORDER BY "MM"."CREATED_AT", "MM"."ID"
    FETCH FIRST ROW ONLY) AS "PROFILE_NAME",
    (SELECT
        "PG"."NAME"
    FROM "PUBLIC"."PERMISSIONS_GROUP_MEMBERSHIP" "PGM"
    INNER JOIN "PUBLIC"."PERMISSIONS_GROUP" "PG"
        ON 1=1
    WHERE ("PGM"."USER_ID" = "C"."USER_ID")
        AND ("PG"."ID" <> 1)
        AND ("PG"."ID" = "PGM"."GROUP_ID")
    ORDER BY 1
    FETCH FIRST ROW ONLY) AS "GROUP_NAME",
    (SELECT
        "AUL"."SOURCE"
    FROM "PUBLIC"."AI_USAGE_LOG" "AUL"
    WHERE "AUL"."CONVERSATION_ID" = "C"."ID"
    ORDER BY "AUL"."CREATED_AT"
    FETCH FIRST ROW ONLY) AS "SOURCE",
    (SELECT
        CASE "AUL"."SOURCE" WHEN 'metabot_agent' THEN 'Metabot' WHEN 'agent' THEN 'Metabot' WHEN 'document_generate_content' THEN 'Documents' WHEN 'example_question_generation_batch' THEN 'Suggested Prompts' WHEN 'slack' THEN 'Slackbot' WHEN 'slackbot' THEN 'Slackbot' WHEN 'oss-sql-gen' THEN 'SQL' WHEN 'sql-gen' THEN 'SQL' WHEN 'unknown' THEN 'Unknown' ELSE "AUL"."SOURCE" END
    FROM "PUBLIC"."AI_USAGE_LOG" "AUL"
    WHERE "AUL"."CONVERSATION_ID" = "C"."ID"
    ORDER BY "AUL"."CREATED_AT"
    FETCH FIRST ROW ONLY) AS "SOURCE_NAME",
    "C"."IP_ADDRESS" AS "IP_ADDRESS",
    "C"."EMBEDDING_HOSTNAME" AS "EMBEDDING_HOSTNAME",
    "C"."EMBEDDING_PATH" AS "EMBEDDING_PATH",
    "C"."USER_AGENT" AS "USER_AGENT",
    "C"."SANITIZED_USER_AGENT" AS "SANITIZED_USER_AGENT",
    MAX("A"."TENANT_ID") AS "TENANT_ID",
    MAX("T"."NAME") AS "TENANT_NAME",
    (SELECT
        "AUL"."MODEL"
    FROM "PUBLIC"."AI_USAGE_LOG" "AUL"
    WHERE "AUL"."CONVERSATION_ID" = "C"."ID"
    ORDER BY "AUL"."CREATED_AT"
    FETCH FIRST ROW ONLY) AS "MODEL"
FROM "PUBLIC"."METABOT_CONVERSATION" "C"
LEFT OUTER JOIN "PUBLIC"."CORE_USER" "U"
    ON "U"."ID" = "C"."USER_ID"
LEFT OUTER JOIN "PUBLIC"."METABOT_MESSAGE" "M"
    ON ("M"."DELETED_AT" IS NULL)
    AND ("M"."CONVERSATION_ID" = "C"."ID")
LEFT OUTER JOIN (
    SELECT
        "CONVERSATION_ID",
        COALESCE(SUM("PROMPT_TOKENS"), 0) AS "PROMPT_TOKENS",
        COALESCE(SUM("COMPLETION_TOKENS"), 0) AS "COMPLETION_TOKENS",
        COALESCE(SUM("TOTAL_TOKENS"), 0) AS "TOTAL_TOKENS",
        MIN("TENANT_ID") AS "TENANT_ID"
    FROM "PUBLIC"."AI_USAGE_LOG"
    WHERE "CONVERSATION_ID" IS NOT NULL
    GROUP BY "CONVERSATION_ID"
) "A"
    ON "A"."CONVERSATION_ID" = "C"."ID"
LEFT OUTER JOIN "PUBLIC"."TENANT" "T"
    ON "T"."ID" = "A"."TENANT_ID"
GROUP BY "C"."ID", "C"."CREATED_AT", "C"."USER_ID", "C"."SUMMARY", "U"."FIRST_NAME", "U"."LAST_NAME", "U"."EMAIL";
--;;
CREATE VIEW "PUBLIC"."V_METABOT_MESSAGES"("MESSAGE_ID", "CONVERSATION_ID", "CREATED_AT", "ROLE", "PROFILE_ID", "TOTAL_TOKENS", "USER_ID", "SLACK_MSG_ID", "CHANNEL_ID") AS
SELECT
    "M"."ID" AS "MESSAGE_ID",
    "M"."CONVERSATION_ID",
    "M"."CREATED_AT",
    "M"."ROLE",
    "M"."PROFILE_ID",
    "M"."TOTAL_TOKENS",
    COALESCE("M"."USER_ID", "C"."USER_ID") AS "USER_ID",
    "M"."SLACK_MSG_ID",
    "M"."CHANNEL_ID"
FROM "PUBLIC"."METABOT_MESSAGE" "M"
INNER JOIN "PUBLIC"."METABOT_CONVERSATION" "C"
    ON 1=1
WHERE ("M"."DELETED_AT" IS NULL)
    AND ("C"."ID" = "M"."CONVERSATION_ID");
--;;
CREATE VIEW "PUBLIC"."V_TENANTS"("TENANT_ID", "ENTITY_QUALIFIED_ID", "NAME", "SLUG", "IS_ACTIVE", "ATTRIBUTES", "CREATED_AT", "UPDATED_AT", "TENANT_COLLECTION_ID", "TENANT_COLLECTION_QUALIFIED_ID") AS
SELECT
    "ID" AS "TENANT_ID",
    'tenant_' || "ID" AS "ENTITY_QUALIFIED_ID",
    "NAME",
    "SLUG",
    "IS_ACTIVE",
    "ATTRIBUTES",
    "CREATED_AT",
    "UPDATED_AT",
    "TENANT_COLLECTION_ID",
    'collection_' || "TENANT_COLLECTION_ID" AS "TENANT_COLLECTION_QUALIFIED_ID"
FROM "PUBLIC"."TENANT";
